{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded database administrator password",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "HIGH",
      "explanation": "The administrator password is stored directly in Terraform source, exposing a privileged database credential to source control and anyone with access to the file."
    },
    {
      "check_id": "CKV_AZURE_96",
      "title": "Infrastructure encryption is not enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The server does not enable infrastructure-level encryption, leaving it without the additional encryption layer available for supported MySQL SKUs."
    },
    {
      "check_id": "CKV_AZURE_94",
      "title": "Geo-redundant backups are not enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The server does not enable geo-redundant backups, reducing resilience if the primary Azure region becomes unavailable."
    },
    {
      "check_id": "CKV_AZURE_53",
      "title": "Public network access is not disabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The configuration does not disable the server's public network endpoint, allowing potential exposure through Azure's public network path."
    },
    {
      "check_id": "CKV_AZURE_54",
      "title": "Minimum TLS version is not explicitly set to TLS 1.2",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "Although SSL enforcement is enabled, the minimum TLS version is not specified, so obsolete TLS versions are not explicitly prohibited."
    },
    {
      "check_id": "CKV_AZURE_127",
      "title": "Threat detection policy is not enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The server has no enabled threat detection policy, limiting detection and notification of suspicious database activity."
    },
    {
      "check_id": "CKV2_AZURE_44",
      "title": "MySQL server has no private endpoint",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "No private endpoint connects the MySQL server to a virtual network, so there is no private network path available when public access is disabled."
    },
    {
      "check_id": "CKV2_AZURE_16",
      "title": "Customer-managed encryption key is not configured",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The server has no associated customer-managed key, preventing customer control over encryption-key lifecycle and revocation."
    }
  ],
  "patched_code": "variable \"mysql_administrator_password\" {\n  description = \"Administrator password for the Azure MySQL server.\"\n  type        = string\n  sensitive   = true\n}\n\nvariable \"mysql_private_endpoint_subnet_id\" {\n  description = \"Resource ID of the subnet used by the MySQL private endpoint.\"\n  type        = string\n}\n\nvariable \"mysql_customer_managed_key_id\" {\n  description = \"Resource ID of the Key Vault key used to encrypt the MySQL server.\"\n  type        = string\n}\n\nresource \"azurerm_mysql_server\" \"changeme_simple_mysql_server\" {\n  name                = \"changeme-simple-mysql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location\n  storage_mb           = 5120\n  sku_name             = \"GP_Gen5_2\"\n  version              = \"8.0\"\n\n  administrator_login          = \"changemeadmin\"\n  administrator_login_password = var.mysql_administrator_password\n\n  infrastructure_encryption_enabled = true\n  geo_redundant_backup_enabled      = true\n  public_network_access_enabled     = false\n  ssl_enforcement_enabled           = true\n  ssl_minimal_tls_version_enforced  = \"TLS1_2\"\n\n  identity {\n    type = \"SystemAssigned\"\n  }\n\n  threat_detection_policy {\n    enabled              = true\n    email_account_admins = true\n  }\n}\n\nresource \"azurerm_mysql_server_key\" \"changeme_simple_mysql_server\" {\n  server_id        = azurerm_mysql_server.changeme_simple_mysql_server.id\n  key_vault_key_id = var.mysql_customer_managed_key_id\n}\n\nresource \"azurerm_private_endpoint\" \"changeme_simple_mysql_server\" {\n  name                = \"changeme-simple-mysql-private-endpoint\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location\n  subnet_id           = var.mysql_private_endpoint_subnet_id\n\n  private_service_connection {\n    name                           = \"changeme-simple-mysql-private-connection\"\n    private_connection_resource_id = azurerm_mysql_server.changeme_simple_mysql_server.id\n    subresource_names              = [\"mysqlServer\"]\n    is_manual_connection           = false\n  }\n}\n",
  "fix_summary": "Replaced the hardcoded administrator password with a sensitive input variable and enabled infrastructure encryption, geo-redundant backups, TLS 1.2, threat detection, and private-only network access. The SKU was upgraded to support the security features, and resources were added for a private endpoint and a caller-supplied customer-managed Key Vault key."
}
